style.css:
@-moz-document domain("chat.openai.com") {
body {
    background: linear-gradient(135deg, #1a0023 0%, #3a005f 100%) fixed;
    color: #00ffe7;
    font-family: 'Orbitron', 'Arial', sans-serif;
  }

  header, nav, footer {
    background: rgba(0, 0, 0, 0.7);
    border-bottom: 1px solid #ff00c8;
  }

  .chat-message, .message, .text-base {
    background: rgba(255, 0, 200, 0.15);
    border-radius: 12px;
    padding: 12px;
    margin-bottom: 10px;
    box-shadow: 0 0 10px #ff00c8;
    color: #00ffe7;
  }

  button, input, select, textarea {
    background-color: rgba(0, 0, 0, 0.4);
    color: #00ffe7;
    border: 1px solid #00ffe7;
    border-radius: 6px;
  }

  a {
    color: #ff8ae2;
    text-decoration: underline;
  }

  /* Hover Effects */
  button:hover, input:hover, select:hover, textarea:hover {
    background-color: rgba(0, 0, 0, 0.6);
    border-color: #ff00c8;
  }

  /* Animation background subtle */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: radial-gradient(circle at 50% 50%, rgba(255,0,200,0.1) 0%, transparent 70%);
    animation: pulse 5s infinite alternate;
    z-index: -1;
  }

  @keyframes pulse {
    0% { opacity: 0.7; }
    100% { opacity: 0.3; }
  }
}
